const models = [
 {id:'C01',name:'Recuerdo lila',colors:['Morado','Blanco'],description:'Flores blancas con un centro lila y detalles morados.',image:'assets/corona-01.webp'},
 {id:'C02',name:'Luz naranja',colors:['Naranja','Blanco'],description:'Una corona clara con flores y acentos naranja.',image:'assets/corona-02.webp'},
 {id:'C03',name:'Cariño rosa',colors:['Rosa','Blanco'],description:'Flores en tonos rosas y claros, con un centro floral cálido.',image:'assets/corona-03.webp'},
 {id:'C04',name:'Rayito de sol',colors:['Amarillo','Blanco'],description:'Un centro de flores amarillas entre flores blancas y hojas verdes.',image:'assets/corona-04.webp'},
 {id:'C05',name:'Abrazo naranja',colors:['Naranja','Blanco'],description:'Flores naranja intensas combinadas con flores blancas.',image:'assets/corona-05.webp'},
 {id:'C06',name:'Suspiro turquesa',colors:['Azul','Blanco'],description:'Rosas turquesa al centro, rodeadas de flores claras y follaje verde.',image:'assets/corona-06.webp'},
 {id:'C07',name:'Pétalos de cariño',colors:['Rosa','Blanco'],description:'Flores blancas con detalles rosas distribuidos alrededor de la corona.',image:'assets/corona-07.webp'},
 {id:'C08',name:'Cielo azul',colors:['Azul','Blanco'],description:'Flores azules al centro, con flores blancas y detalles en azul.',image:'assets/corona-08.webp'},
 {id:'C09',name:'Verde esperanza',colors:['Verde','Blanco'],description:'Flores de tonos verdes y claros con detalles de follaje.',image:'assets/corona-09.webp'},
 {id:'C10',name:'Memoria dorada',colors:['Amarillo','Blanco'],description:'Rosas amarillas al centro y pequeños acentos entre flores blancas.',image:'assets/corona-10.webp'},
 {id:'C11',name:'Siempre en rosa',colors:['Rosa','Blanco'],description:'Un centro de rosas y detalles rosas sobre una corona de flores blancas.',image:'assets/corona-11.webp'}
];
const $=id=>document.getElementById(id);
const palette=[['Rosa','#D63384'],['Blanco','#fffdf5'],['Morado','#8054A5'],['Azul','#39a4ca'],['Amarillo','#f3ca36'],['Naranja','#ed8931'],['Verde','#397457']];
let activeFilter='Todas',shown=[...models],selected=null,viewIndex=0,opener=null;
const gallery=$('gallery'),form=$('order-form'),dialog=$('model-dialog');
function makeButton(text,action,className=''){const b=document.createElement('button');b.type='button';b.textContent=text;b.className=className;b.addEventListener('click',action);return b;}
function renderGallery(){gallery.replaceChildren();shown=models.filter(m=>activeFilter==='Todas'||m.colors.includes(activeFilter));shown.forEach(m=>{const card=document.createElement('article');card.className='model-card';const photo=makeButton('',e=>openModel(m.id,e.currentTarget),'model-photo');photo.setAttribute('aria-label','Ver foto completa: '+m.name);const img=document.createElement('img');img.src=m.image;img.alt='Corona '+m.id+': '+m.description;img.loading='lazy';img.width=1200;img.height=1600;const caption=document.createElement('span');caption.className='photo-expand';caption.textContent='Ver de cerca';photo.append(img,caption);const code=document.createElement('p');code.className='model-code';code.textContent=m.id+' · HECHA A MANO';const title=document.createElement('h3');title.textContent=m.name;const colors=document.createElement('p');colors.className='model-colors';colors.textContent=m.colors.join(' + ');card.append(photo,code,title,colors,makeButton('Quiero una como esta',()=>{selectModel(m);goToOrder();},'choose-model'));gallery.append(card);});gallery.scrollLeft=0;$('gallery-count').textContent=shown.length+' '+(shown.length===1?'modelo':'modelos');requestAnimationFrame(updateGalleryButtons);}
function updateGalleryButtons(){$('gallery-prev').disabled=gallery.scrollLeft<4;$('gallery-next').disabled=gallery.scrollLeft+gallery.clientWidth>=gallery.scrollWidth-4;}
['Todas',...palette.filter(p=>p[0]!=='Blanco').map(p=>p[0])].forEach(label=>{const b=makeButton(label,()=>{activeFilter=label;for(const button of $('filters').children)button.setAttribute('aria-pressed',String(button.textContent===label));renderGallery();});b.setAttribute('aria-pressed',String(label==='Todas'));$('filters').append(b);});
palette.forEach(([name,color])=>{const label=document.createElement('label');label.className='color-choice';const input=document.createElement('input');input.type='checkbox';input.name='colors';input.value=name;const span=document.createElement('span');const dot=document.createElement('i');dot.className='color-swatch';dot.style.setProperty('--swatch',color);span.append(dot,document.createTextNode(name));label.append(input,span);$('color-picker').append(label);});
models.forEach(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=m.id+' · '+m.name;$('model-select').append(o);});
function setColors(colors){for(const c of form.querySelectorAll('[name=colors]'))c.checked=colors.includes(c.value);}
function updatePreview(){if(selected){$('selected-image').src=selected.image;$('selected-image').alt='Modelo seleccionado: '+selected.name;$('selected-title').textContent=selected.id+' · '+selected.name;$('selected-description').textContent=selected.colors.join(' + ');$('clear-model').hidden=false;}else{$('selected-image').src='assets/chalia-logo.webp';$('selected-image').alt='Logo de Coronas Chalía';$('selected-title').textContent='Tu propia idea';$('selected-description').textContent='Elige los colores y cuéntanos cómo la imaginas.';$('clear-model').hidden=true;}}
function selectModel(m){selected=m;form.querySelector('[name=intent][value=modelo]').checked=true;$('model-field').hidden=false;$('model-select').value=m.id;setColors(m.colors);updatePreview();updateMessage();clearFeedback();}
function setCustom(){selected=null;form.querySelector('[name=intent][value=personalizada]').checked=true;$('model-field').hidden=true;$('model-select').value='';$('model-select').required=false;updatePreview();updateMessage();clearFeedback();}
function goToOrder(){document.querySelector('#pedido').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function renderDialog(){const m=shown[viewIndex];$('dialog-image').src=m.image;$('dialog-image').alt=m.description;$('dialog-code').textContent=m.id+' · CORONA ARTESANAL';$('dialog-title').textContent=m.name;$('dialog-description').textContent=m.description;$('dialog-position').textContent=(viewIndex+1)+' / '+shown.length;$('dialog-prev').disabled=shown.length<2;$('dialog-next').disabled=shown.length<2;}
function openModel(id,source){viewIndex=shown.findIndex(m=>m.id===id);opener=source;renderDialog();dialog.showModal();document.body.style.overflow='hidden';}
function closeDialog(){dialog.close();}
dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('dialog-close').addEventListener('click',closeDialog);$('dialog-prev').addEventListener('click',()=>{viewIndex=(viewIndex-1+shown.length)%shown.length;renderDialog();});$('dialog-next').addEventListener('click',()=>{viewIndex=(viewIndex+1)%shown.length;renderDialog();});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();viewIndex=(viewIndex+(e.key==='ArrowRight'?1:-1)+shown.length)%shown.length;renderDialog();}});$('dialog-order').addEventListener('click',()=>{selectModel(shown[viewIndex]);closeDialog();goToOrder();});
document.querySelectorAll('[data-custom]').forEach(a=>a.addEventListener('click',setCustom));$('clear-model').addEventListener('click',setCustom);
form.querySelectorAll('[name=intent]').forEach(input=>input.addEventListener('change',()=>{if(input.value==='personalizada')setCustom();else{$('model-field').hidden=false;$('model-select').required=true;updateMessage();}}));$('model-select').addEventListener('change',()=>{const m=models.find(m=>m.id===$('model-select').value);if(m)selectModel(m);else{selected=null;updatePreview();updateMessage();}});
$('gallery-prev').addEventListener('click',()=>gallery.scrollBy({left:-gallery.clientWidth*.85,behavior:'smooth'}));$('gallery-next').addEventListener('click',()=>gallery.scrollBy({left:gallery.clientWidth*.85,behavior:'smooth'}));gallery.addEventListener('scroll',updateGalleryButtons,{passive:true});window.addEventListener('resize',updateGalleryButtons);
function getOrderData(){const values=new FormData(form);return{name:String(values.get('name')||'').trim(),intent:String(values.get('intent')),model:selected,colors:values.getAll('colors'),size:String(values.get('size')),quantity:String(values.get('quantity')),date:String(values.get('date')||''),idea:String(values.get('idea')||'').trim()};}
function buildMessage(data){const lines=['Hola, Chalía. Me gustaría consultar un pedido de coronas artesanales.','',`Mi nombre: ${data.name||'(tu nombre)'}`,`Busco: ${data.intent==='modelo'?'una corona como el modelo de la galería':'una corona personalizada'}`];if(data.intent==='modelo'&&data.model){lines.push(`Modelo de referencia: ${data.model.id} · ${data.model.name}`,`Foto: ${new URL(data.model.image,window.location.href).href}`);}lines.push(`Colores: ${data.colors.length?data.colors.join(', '):'Por definir con Chalía'}`,`Tamaño: ${data.size}`,`Cantidad: ${data.quantity}`);if(data.date){const [y,m,d]=data.date.split('-');lines.push(`Fecha deseada: ${d}/${m}/${y}`);}if(data.idea)lines.push(`Mi idea: ${data.idea}`);lines.push('','¿Me confirmas precio, disponibilidad y cómo acordamos la entrega?','Vi tus coronas en '+window.location.origin+'/');return lines.join('\n');}
function updateMessage(){$('message-content').textContent=buildMessage(getOrderData());}
function clearFeedback(){$('form-error').hidden=true;$('form-feedback').hidden=true;}
form.addEventListener('input',()=>{updateMessage();clearFeedback();});form.addEventListener('change',()=>{updateMessage();clearFeedback();});
$('toggle-message').addEventListener('click',()=>{const open=$('message-content').hidden;$('message-content').hidden=!open;$('toggle-message').setAttribute('aria-expanded',String(open));$('toggle-message').textContent=open?'Ocultar mi mensaje':'Revisar mi mensaje';updateMessage();});
const today=new Date();const localToday=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;$('date').min=localToday;
form.addEventListener('submit',e=>{e.preventDefault();clearFeedback();if(!form.reportValidity())return;const data=getOrderData();let error='';if(!data.name)error='Escribe tu nombre para preparar el mensaje.';else if(data.intent==='modelo'&&!data.model)error='Elige un modelo de la galería o selecciona una idea personalizada.';else if(data.date&&data.date<localToday)error='Elige una fecha de hoy en adelante.';if(error){$('form-error').textContent=error;$('form-error').hidden=false;return;}const url='https://wa.me/522292198913?text='+encodeURIComponent(buildMessage(data));$('whatsapp-fallback').href=url;$('form-feedback').hidden=false;window.open(url,'_blank','noopener,noreferrer');});
renderGallery();updateMessage();
const context=document.modelContext;
if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'configure_corona_order',title:'Preparar una consulta de corona',description:'Selecciona un modelo y prepara los detalles visibles del formulario. No envía mensajes ni abre WhatsApp.',inputSchema:{type:'object',properties:{modelId:{type:'string',enum:models.map(m=>m.id)},name:{type:'string',maxLength:80},idea:{type:'string',maxLength:1500}},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Datos inválidos');for(const k of Object.keys(input))if(!['modelId','name','idea'].includes(k))throw new Error('Campo no válido');if(input.modelId!==undefined&&!models.some(m=>m.id===input.modelId))throw new Error('Modelo no válido');if(input.name!==undefined&&(typeof input.name!=='string'||input.name.length>80))throw new Error('Nombre no válido');if(input.idea!==undefined&&(typeof input.idea!=='string'||input.idea.length>1500))throw new Error('Idea no válida');if(input.modelId)selectModel(models.find(m=>m.id===input.modelId));else setCustom();if(input.name!==undefined)$('name').value=input.name;if(input.idea!==undefined)$('idea').value=input.idea;updateMessage();goToOrder();return{status:'prepared',modelId:selected?.id??null,name:$('name').value,message:buildMessage(getOrderData()),sent:false};}})).catch(()=>{});}catch{}}
